/** A pluggable cast backend (Google Cast, AirPlay bridge, etc.). */
export interface CastProvider {
  readonly id: string;
  readonly name: string;
  isAvailable(): Promise<boolean>;
  connect(): Promise<void>;
  disconnect(): Promise<void>;
}

/** Cast configuration. */
export interface CastOptions {
  readonly providers?: readonly CastProvider[];
}

/** Returns true when at least one cast provider is configured. */
export function canCast(options: CastOptions = {}): boolean {
  return (options.providers?.length ?? 0) > 0;
}

/** Connects to a cast provider. */
export async function connectCast(provider: CastProvider): Promise<void> {
  await provider.connect();
}

/** Disconnects from a cast provider. */
export async function disconnectCast(provider: CastProvider): Promise<void> {
  await provider.disconnect();
}

/** Returns the first available provider, or null. */
export async function findAvailableCastProvider(
  options: CastOptions,
): Promise<CastProvider | null> {
  for (const provider of options.providers ?? []) {
    if (await provider.isAvailable()) {
      return provider;
    }
  }

  return null;
}
